//! Slint GUI for Universal Drive Manager.
//!
//! The GUI never touches devices or the file system directly: all discovery
//! goes through [`udm_app::DiscoveryService`], which runs on a background
//! worker. This crate converts domain data into view models
//! ([`view_model`]), applies them to the window ([`presenter`]) and wires UI
//! callbacks (in the binary).

/// Code generated by `slint-build` from `ui/main.slint`. Generated code is not
/// held to the workspace lint policy.
#[allow(
    clippy::all,
    clippy::pedantic,
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::todo,
    clippy::dbg_macro,
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    unreachable_pub,
    missing_debug_implementations,
    unsafe_code
)]
mod generated {
    slint::include_modules!();
}

pub use generated::*;

pub mod presenter;
pub mod view_model;
